"""A local-only, one-QR onboarding screen; Android performs the privileged authorization."""


def setup_page():
    return '''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Синхро · Настройка</title>
<style>:root{font:16px system-ui;color-scheme:dark;background:#111214;color:#f6f5ef}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 50% 15%,#302b1b,transparent 50%)}header{max-width:1060px;margin:auto;padding:26px;font-size:20px;font-weight:650}header span{color:#ffd34e}main{max-width:960px;margin:12px auto;padding:0 24px 40px;text-align:center}h1{font-size:clamp(29px,4vw,44px);letter-spacing:-1.5px;margin-bottom:12px}.lead{color:#a4a7ad;line-height:1.7}.layout{display:grid;grid-template-columns:1fr 1fr;gap:24px;text-align:left;margin-top:28px}.panel{border:1px solid #34363b;border-radius:28px;background:#1c1e21;padding:26px}.step{display:flex;gap:14px;margin:20px 0;color:#a4a7ad;line-height:1.6}.number{color:#ffd34e;font-weight:700}strong{color:#f6f5ef}.qr{margin:14px auto 22px;background:white;border-radius:20px;padding:14px;width:270px;height:270px}.qr svg{width:100%;height:100%;shape-rendering:crispEdges}button,a.button{display:block;width:100%;border:0;border-radius:15px;background:#ffd34e;color:#191a1e;padding:16px;font:600 14px system-ui;cursor:pointer;text-align:center;text-decoration:none;margin-top:12px}.secondary{background:#2a2d32!important;color:#f6f5ef!important}#message{font-size:14px;line-height:1.6;color:#d0c7a5;text-align:center;min-height:42px}.hint,footer{font-size:12px;line-height:1.7;color:#858993}a{color:#ffd34e}#devices button{font-size:13px}#install{display:none}footer{margin-top:24px}@media(max-width:700px){.layout{grid-template-columns:1fr}.qr{width:230px;height:230px}}[hidden]{display:none!important}</style>
<header><span>⇄</span> Синхро</header><main><h1>Один QR. Ваш телефон подключён.</h1><p class="lead">Видео, вкладки и автоматический буфер обмена между телефоном и ПК.</p>
<div class="layout"><section class="panel"><div class="step"><span class="number">01</span><div><strong>Откройте беспроводную отладку</strong><br>Настройки телефона → Для разработчиков → Беспроводная отладка.</div></div><div class="step"><span class="number">02</span><div><strong>Выберите «Сопряжение по QR-коду»</strong><br>Сканируйте код справа именно этим системным сканером.</div></div><div class="step"><span class="number">03</span><div><strong>Нажмите «Установить и подключить»</strong><br>Синхро установится на телефон, сохранит адрес ПК и включит буфер. Порты и коды вводить не нужно.</div></div><p class="hint">Сопряжение даёт этому ПК доступ ADB к телефону и нужно для чтения системного буфера в фоне. Root не требуется. На обычный просмотр видео этот шаг не влияет.</p><a href="/pair">Только видео и ручной обмен — обычный QR приложения</a></section>
<section class="panel"><div class="qr" id="qr"></div><p id="message">Готовим защищённый QR-код…</p><div id="devices"></div><button id="install">Установить и подключить</button><button id="refresh" class="secondary">Обновить QR-код</button></section></div>
<section class="panel" style="margin-top:24px"><strong>Обновления Windows</strong><p id="updateMessage" class="lead">Проверяем версию…</p><button id="updateCheck" class="secondary">Проверить GitHub Releases</button><button id="updateInstall" hidden>Установить обновление и перезапустить</button></section><footer>Телефон и ПК должны быть в одной Wi-Fi сети. Для браузера на ПК: <a href="/chrome-extension.zip">расширение Синхро для Chrome</a>.<br>Распакуйте ZIP → chrome://extensions → Режим разработчика → Загрузить распакованное расширение.</footer></main>
<script>
let currentDevice=null,lastSvg='';const $=id=>document.getElementById(id);
async function call(path,body){const result=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});if(!result.ok)throw Error('Запустите актуальный сервис Синхро на этом ПК');return result.json()}
function render(state){$('message').textContent=state.message;if(state.qrSvg&&state.qrSvg!==lastSvg){lastSvg=state.qrSvg;$('qr').innerHTML=state.qrSvg}currentDevice=state.device||null;$('install').style.display=state.stage==='paired'?'block':'none';$('devices').replaceChildren();if(state.stage==='scan'&&state.devices?.length){for(const device of state.devices){const b=document.createElement('button');b.className='secondary';b.textContent='Использовать подключённый '+device.name;b.onclick=()=>finish(device.id);$('devices').append(b)}}if(state.stage==='done')$('qr').hidden=true;else $('qr').hidden=false}
async function begin(){try{render(await call('/local/setup/start',{}))}catch(error){$('message').textContent=error.message}}
async function finish(device){try{render(await call('/local/setup/install',{device}))}catch(error){$('message').textContent=error.message}}
function renderUpdate(state){$('updateMessage').textContent='Сейчас '+state.current+' · '+state.message;$('updateInstall').hidden=state.stage!=='available'||!state.portable;if(state.stage==='available'&&!state.portable)$('updateMessage').textContent+=' · Для исходников: git pull';}
$('updateCheck').onclick=async()=>{try{renderUpdate(await call('/local/updates/check',{}))}catch(e){$('updateMessage').textContent=e.message}};
$('updateInstall').onclick=async()=>{try{renderUpdate(await call('/local/updates/install',{}))}catch(e){$('updateMessage').textContent=e.message}};
call('/local/updates/check',{}).then(renderUpdate).catch(()=>{});setInterval(()=>call('/local/updates/status').then(renderUpdate).catch(()=>{}),1500);
$('install').onclick=()=>finish(currentDevice);$('refresh').onclick=begin;begin();setInterval(async()=>{try{render(await call('/local/setup/status'))}catch(error){$('message').textContent=error.message}},1000);
</script></html>'''
